import { promises as fs } from "node:fs";
import path from "node:path";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
export const revalidate = 0;

/** 状態ファイル (生成物内・外部送信なし) */
const STATE_FILE = ".soloptilink/build-state.json";

/** 更新が 24 時間以上ない状態は「完成扱い」に倒す (バナーの焼き付き防止) */
const STALE_MS = 24 * 60 * 60 * 1000;

const NO_STORE = { "Cache-Control": "no-store" };

/** 非表示応答 (complete 扱い)。理由は診断用であり画面には出さない */
function hidden(reason: string): Response {
  return Response.json(
    { state: "complete", visible: false, reason },
    { headers: NO_STORE },
  );
}

export async function GET(): Promise<Response> {
  // 本番ビルドでは状態表示を出さない (お客様の本番環境に開発中の表示を残さない)
  if (process.env.NODE_ENV !== "development") {
    return hidden("production");
  }
  try {
    const file = path.join(process.cwd(), STATE_FILE);
    const raw = await fs.readFile(file, "utf8");
    const doc = JSON.parse(raw) as {
      state?: unknown;
      updated_at?: unknown;
      note_ja?: unknown;
    };
    const state = doc && typeof doc.state === "string" ? doc.state : "";
    if (state !== "generating" && state !== "verifying") {
      return hidden("not_in_progress");
    }
    const updatedAt =
      typeof doc.updated_at === "string" ? Date.parse(doc.updated_at) : NaN;
    if (Number.isFinite(updatedAt) && Date.now() - updatedAt > STALE_MS) {
      return hidden("stale");
    }
    return Response.json(
      {
        state,
        visible: true,
        note_ja: typeof doc.note_ja === "string" ? doc.note_ja : "",
      },
      { headers: NO_STORE },
    );
  } catch (e) {
    // 状態ファイル欠落・JSON 破損・権限不足 → 非表示
    // (状態表示の故障が新たな顧客可視エラーになってはならない)
    return hidden("state_unavailable");
  }
}
